Here is the commit message:
usb: host: fotg2: Fix potential NULL dereference

There is code in the .remove() hook to handle the drvdata
being NULL, for good reasons: it is never set, so it will
always be NULL. As I moved code around, static checkers
start complaining.

Instead of this, make sure to always set it on successful
probe so we can always dereference it on the remove path.

Use the platform_device_[set|get]_drvdata() since this is
a platform device.

Fixes: ffa8a31b5b3b ("usb: host: fotg2: add silicon clock handling")
Reported-by: Dan Carpenter <dan.carpenter@oracle.com>
Cc: Dan Carpenter <dan.carpenter@oracle.com>
Signed-off-by: Linus Walleij <linus.walleij@linaro.org>
Signed-off-by: Greg Kroah-Hartman <gregkh@linuxfoundation.org>

Here is the root cause:
The bug was caused by the `drvdata` not being set during the probe process, leading to a potential NULL dereference when attempting to access it in the remove function. This oversight could result in dereferencing a NULL pointer if the remove function was called without a successful probe, which static checkers flagged as a potential issue.

Here is the patch:
  */
 static int fotg210_hcd_probe(struct platform_device *pdev)
 {
 	struct device *dev = &pdev->dev;
 	struct usb_hcd *hcd;
 	struct resource *res;
 	int irq;
 	int retval = -ENODEV;
 	struct fotg210_hcd *fotg210;

 	if (usb_disabled())
 		return -ENODEV;

 	pdev->dev.power.power_state = PMSG_ON;

 	res = platform_get_resource(pdev, IORESOURCE_IRQ, 0);
 	if (!res) {
 		dev_err(dev, "Found HC with no IRQ. Check %s setup!\n",
 				dev_name(dev));
 		return -ENODEV;
 	}

 	irq = res->start;

 	hcd = usb_create_hcd(&fotg210_fotg210_hc_driver, dev,
 			dev_name(dev));
 	if (!hcd) {
 		dev_err(dev, "failed to create hcd with err %d\n", retval);
 		retval = -ENOMEM;
 		goto fail_create_hcd;
 	}

 	hcd->has_tt = 1;

 	res = platform_get_resource(pdev, IORESOURCE_MEM, 0);
 	hcd->regs = devm_ioremap_resource(&pdev->dev, res);
 	if (IS_ERR(hcd->regs)) {
 		retval = PTR_ERR(hcd->regs);
 		goto failed_put_hcd;
 	}

 	hcd->rsrc_start = res->start;
 	hcd->rsrc_len = resource_size(res);

 	fotg210 = hcd_to_fotg210(hcd);

 	fotg210->caps = hcd->regs;

 	/* It's OK not to supply this clock */
 	fotg210->pclk = clk_get(dev, "PCLK");
 	if (!IS_ERR(fotg210->pclk)) {
 		retval = clk_prepare_enable(fotg210->pclk);
 		if (retval) {
 			dev_err(dev, "failed to enable PCLK\n");
 			goto failed_put_hcd;
 		}
 	} else if (PTR_ERR(fotg210->pclk) == -EPROBE_DEFER) {
 		/*
 		 * Percolate deferrals, for anything else,
 		 * just live without the clocking.
 		 */
 		retval = PTR_ERR(fotg210->pclk);
 		goto failed_dis_clk;
 	}

 	retval = fotg210_setup(hcd);
 	if (retval)
 		goto failed_dis_clk;

 	fotg210_init(fotg210);

 	retval = usb_add_hcd(hcd, irq, IRQF_SHARED);
 	if (retval) {
 		dev_err(dev, "failed to add hcd with err %d\n", retval);
 		goto failed_dis_clk;
 	}
 	device_wakeup_enable(hcd->self.controller);
+	platform_set_drvdata(pdev, hcd);

 	return retval;

 failed_dis_clk:
 	if (!IS_ERR(fotg210->pclk))
 		clk_disable_unprepare(fotg210->pclk);
 failed_put_hcd:
 	usb_put_hcd(hcd);
 fail_create_hcd:
 	dev_err(dev, "init %s fail, %d\n", dev_name(dev), retval);
 	return retval;
 }

  */
 static int fotg210_hcd_remove(struct platform_device *pdev)
 {
-	struct device *dev = &pdev->dev;
-	struct usb_hcd *hcd = dev_get_drvdata(dev);
+	struct usb_hcd *hcd = platform_get_drvdata(pdev);
 	struct fotg210_hcd *fotg210 = hcd_to_fotg210(hcd);

 	if (!IS_ERR(fotg210->pclk))
 		clk_disable_unprepare(fotg210->pclk);

-	if (!hcd)
-		return 0;
-
 	usb_remove_hcd(hcd);
 	usb_put_hcd(hcd);

 	return 0;
 }



